# Replaceable analytical asset/tranche contracts for six product variants.
if(!exists('stress_tranche_structure'))library(creditratingsystem)
structured_account_case<-function(template,pool_paths){
 args<-template;first<-pool_paths$cashflows[[1]];origin<-first$date;end<-tail(pool_paths$dates,1)[[1]];amount<-first$principal_available+first$interest_available+first$recovery_gross;args$as_of<-origin;args$scenario_contract$dates<-list(end);args$baseline_cashflows<-list(list(scenario_id='s',cashflow_id='cash',date=end,amount=amount));args$exposure_paths<-list(list(scenario_id='s',exposure_id='account',date=end,signed_replacement_mark=0));args$collateral_paths<-list(list(scenario_id='s',netting_set_id='net',date=end,known_at=origin,collateral_value=0,haircut=0));args$settlement_terms[[1]]$estate_delay_days<-0;args$settlement_terms[[1]]$collateral_delay_days<-0;args$settlement_terms[[1]]$replacement_cost<-0;args$settlement_terms[[1]]$replacement_delay_days<-0;args$party_default_paths<-list(list(scenario_id='s',default_group_id='bank',date=end,conditional_pd=1,default_channel='bank'));args$shared_innovations<-list(list(scenario_id='s',date=end,channel_id='bank',uniform=.5));do.call(stress_pool_counterparties,args)$value
}
run_securitization_products<-function(data=NULL,verify_reference=TRUE){
 if(is.null(data))data<-jsonlite::fromJSON(system.file('extdata/securitization_products.json',package='creditratingsystem'),simplifyVector=FALSE);out<-errors<-list()
 for(name in names(data$variants)){
 case<-data$variants[[name]];pool<-do.call(build_credit_asset_pool,case$pool_input)$value;args<-case$path_input;args$asset_pool<-pool;paths<-do.call(simulate_asset_pool,args)$value;waterfall<-run_tranche_waterfall(paths,case$structure_profile)$value;origin<-paths$origin;horizon<-as.numeric(as.Date(tail(paths$dates,1)[[1]])-as.Date(origin));target<-list(event='ULTIMATE_PRINCIPAL',horizon=horizon,time_unit='days',probability_measure='PHYSICAL',conditioning=paths$scenario_contract$conditioning);discount<-setNames(rep(list(1),length(case$structure_profile$payment_dates)),unlist(case$structure_profile$payment_dates,use.names=FALSE));metrics<-estimate_tranche_credit_metrics(waterfall,target,discount)$value;args<-case$credit_stress_input;args$asset_pool<-pool;stressed_paths<-do.call(simulate_asset_pool,args)$value;stressed_waterfall<-run_tranche_waterfall(stressed_paths,case$structure_profile)$value;stress<-stress_tranche_structure(waterfall,list(list(alternative_id='debtor_default',tranche_paths=stressed_waterfall,assumption='First debtor defaults on the first risk date under the same supplied innovations')),target,discount)$value;account<-structured_account_case(data$account_stress_template,paths);static<-tranche_loss_from_pool(c(.1,.15,.2),.1,.2,100)$value;senior<-metrics$metrics[[1]];subject<-list(subject_id=paste0(name,'-senior'),subject_type='issue');components<-list(c(list(component_id=paste0(name,'-pd'),quantity='PD',value=senior$event_probability),subject,list(variant='ultimate_principal',definition=target)),c(list(component_id=paste0(name,'-el'),quantity='EL',value=senior$expected_ultimate_principal_loss,currency='EUR'),subject,list(variant='ultimate_principal',definition=target)));binding<-list(profile_id=name,profile_version='1',model_id=case$structure_profile$structure_id,model_version=case$structure_profile$version,model_hash=waterfall$structure_hash,input_hash=paths$sha256);assessment<-compose_risk_assessment(paste0(name,'-assessment'),subject,components,binding,origin,origin,origin)$value;error<-tryCatch(do.call(build_credit_asset_pool,case$invalid_pool_input),error=identity);stopifnot(inherits(error,'creditratingsystem_error'));errors[[name]]<-error$code;out[[name]]<-list(pool=pool,paths=paths,waterfall=waterfall,metrics=metrics,credit_stress=stress,account_stress=account,static_boundary=static,assessment=assessment)
 }
 if(verify_reference){same<-function(a,b)stopifnot(is.finite(a),abs(a-b)<=1e-10+1e-12*abs(b));first_principal<-c(ABS=100,RMBS=100,CMBS=20,CLO=0,revolving_pool=0,static_pool=40);coupons<-c(ABS=5,RMBS=5,CMBS=9,CLO=10,revolving_pool=10,static_pool=8);for(name in names(out)){r<-out[[name]];same(r$paths$cashflows[[1]]$principal_available,first_principal[[name]]);same(sum(vapply(r$paths$cashflows,function(x)x$interest_available,0.)),coupons[[name]]);same(sum(vapply(r$metrics$metrics,function(x)x$expected_ultimate_principal_loss,0.)),0);same(sum(vapply(r$credit_stress$comparisons[[1]]$metrics$metrics,function(x)x$expected_ultimate_principal_loss,0.)),75);a<-r$account_stress$ending_states[[1]];same(a$credit_loss,a$baseline_cash/2);stopifnot(max(abs(unlist(r$static_boundary$tranche_loss_fraction)-c(0,.5,1)))<1e-12,r$assessment$composition_status=='CONSISTENT',errors[[name]]==data$variants[[name]]$expected_error)};for(name in c('CLO','revolving_pool')){purchase<-out[[name]]$paths$acquisitions[[1]];same(purchase$purchase_price,50);same(purchase$acquired_principal,50);stopifnot(purchase$acquired)};stopifnot(length(out$static_pool$paths$acquisitions)==0L)}
 list(data_origin=data$data_origin,version=data$version,product=data$product,variants=out,contract_error_codes=errors)
}
